import * as React from 'react';
import { cn } from '@/lib/utils';

export type LogoItem = {
  /** Accessible name announced for the logo. */
  name: string;
  /** Logo artwork. Mark the image decorative so the name is not duplicated. */
  logo: React.ReactNode;
  /** Optional destination. */
  href?: string;
};

export type LogoCloudProps = React.HTMLAttributes<HTMLDivElement> & {
  /** Logos to display. */
  items: LogoItem[];
  /** Caption above the strip. */
  caption?: string;
  /** Desktop column count (3-6). Default 4. */
  columns?: 3 | 4 | 5 | 6;
  /** Desaturate logos until hover. Default true. */
  grayscale?: boolean;
  /** Logo box height. Default 'md'. */
  size?: 'sm' | 'md' | 'lg';
  /** Caption and grid alignment. Default 'center'. */
  align?: 'left' | 'center';
  /** Custom link element for routers. */
  linkComponent?: React.ElementType;
};

const columnClasses: Record<NonNullable<LogoCloudProps['columns']>, string> = {
  3: 'grid-cols-2 sm:grid-cols-3',
  4: 'grid-cols-2 sm:grid-cols-4',
  5: 'grid-cols-2 sm:grid-cols-3 lg:grid-cols-5',
  6: 'grid-cols-2 sm:grid-cols-3 lg:grid-cols-6',
};

const sizeClasses: Record<NonNullable<LogoCloudProps['size']>, string> = {
  sm: 'h-6',
  md: 'h-8',
  lg: 'h-12',
};

/**
 * Trust strip for member, customer or partner logos. Logos are decorative
 * slots; the item name supplies the accessible text. Use it inside a Section
 * so the surface tone and spacing come from the band.
 */
export const LogoCloud = React.forwardRef<HTMLDivElement, LogoCloudProps>(function LogoCloud(
  {
    items,
    caption,
    columns = 4,
    grayscale = true,
    size = 'md',
    align = 'center',
    linkComponent,
    className,
    ...props
  },
  ref
) {
  const Link = linkComponent ?? 'a';
  const logoClass = cn(
    'flex items-center transition duration-200 motion-reduce:transition-none',
    sizeClasses[size],
    grayscale && 'opacity-70 grayscale hover:opacity-100 hover:grayscale-0'
  );

  return (
    <div ref={ref} className={cn('w-full', className)} {...props}>
      {caption && (
        <p
          className={cn(
            'mb-6 text-xs font-semibold uppercase tracking-widest text-muted-foreground',
            align === 'center' && 'text-center'
          )}
        >
          {caption}
        </p>
      )}
      <ul className={cn('grid items-center gap-x-8 gap-y-6', columnClasses[columns], align === 'center' && 'justify-items-center')}>
        {items.map((item) => {
          const content = (
            <>
              <span className={logoClass} aria-hidden="true">
                {item.logo}
              </span>
              <span className="sr-only">{item.name}</span>
            </>
          );

          return (
            <li key={item.name} className={cn('min-w-0', align === 'center' ? 'justify-self-center' : 'justify-self-start')}>
              {item.href ? (
                <Link
                  href={item.href}
                  className="rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
                >
                  {content}
                </Link>
              ) : (
                content
              )}
            </li>
          );
        })}
      </ul>
    </div>
  );
});

{
  "id": "logo-cloud",
  "name": "LogoCloud",
  "tier": "molecule",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.6.0",
  "sourceDir": "logo-cloud",
  "exportName": "LogoCloud",
  "description": "Trust strip for member, customer or partner logos with captions, columns and optional links.",
  "designIntent": "Proof logos are repeated on every marketing page with inconsistent sizing, spacing and alt text. LogoCloud makes the strip a named list, keeps the logos decorative and supplies the accessible name once.",
  "props": [
    {
      "name": "items",
      "type": "LogoItem[]",
      "required": true,
      "description": "Logos to display: accessible name, decorative artwork and optional href."
    },
    {
      "name": "caption",
      "type": "string",
      "required": false,
      "description": "Caption above the strip."
    },
    {
      "name": "columns",
      "type": "3 | 4 | 5 | 6",
      "required": false,
      "defaultValue": "4",
      "description": "Desktop column count."
    },
    {
      "name": "grayscale",
      "type": "boolean",
      "required": false,
      "defaultValue": "true",
      "description": "Desaturate logos until hover."
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "required": false,
      "defaultValue": "md",
      "enum": [
        "sm",
        "md",
        "lg"
      ],
      "description": "Logo box height."
    },
    {
      "name": "align",
      "type": "'left' | 'center'",
      "required": false,
      "defaultValue": "center",
      "enum": [
        "left",
        "center"
      ],
      "description": "Caption and grid alignment."
    },
    {
      "name": "linkComponent",
      "type": "React.ElementType",
      "required": false,
      "description": "Custom link element for routers."
    }
  ],
  "examples": [
    {
      "title": "Member logo strip",
      "code": "<LogoCloud\n  caption=\"Trusted across the lower middle market\"\n  items={[\n    { name: 'Peakstone', logo: <img src=\"/peakstone.svg\" alt=\"\" /> },\n    { name: 'North', logo: <img src=\"/north.svg\" alt=\"\" />, href: '/members/north' },\n  ]}\n/>",
      "description": "Decorative logo art with the name supplied as accessible text."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't duplicate the name in alt text",
      "explanation": "LogoCloud already renders the item name for assistive tech. Mark the image decorative so screen readers announce it once.",
      "example": "<img src=\"/logo.svg\" alt=\"\" />"
    }
  ],
  "accessibility": [
    {
      "feature": "Named logo list",
      "implementation": "Each item is a list item with an sr-only name; logo artwork is aria-hidden",
      "userRequirements": "Pass a human-readable name for every logo"
    },
    {
      "feature": "Optional links",
      "implementation": "Linked logos render as a single focusable link named by the item",
      "userRequirements": "Use links only when the logo destination is useful"
    }
  ],
  "compositionRules": [
    {
      "component": "Section",
      "relationship": "Place LogoCloud inside a Section so the band controls tone and spacing",
      "example": "<Section tone=\"muted\"><LogoCloud items={logos} /></Section>"
    }
  ],
  "relatedComponents": [
    "Section",
    "Testimonial",
    "StatBand"
  ]
}
